#!/bin/sh
set -eu
cd "$(dirname "$0")"

awk '
{
    ip = $1
    count[ip]++
    if (!(ip in first_seen)) {
        first_seen[ip] = NR
        order[++n] = ip
    }
}
END {
    for (i = 1; i <= n; i++) {
        ip = order[i]
        print count[ip], first_seen[ip], ip
    }
}
' access.log \
| sort -k1,1nr -k2,2n \
| head -n 3 \
| awk '{print $3}'
